// Obtener la primera imagen adjunta y su URL
var attachments = Attachments($feature);
var Link="https://services6.arcgis.com/e5STPBDNmxN8PjAG/arcgis/rest/services/Locales_Nuevos_Adjuntos/FeatureServer/0/"
var complemeto = "/attachments/"
if (Count(attachments) > 0) {
    var firstAttachment = First(attachments);
    var Object=$feature.objectid
    var Fullurl = Link+Object+complemeto+firstAttachment.ID
    return Fullurl;
} else {
    return "No hay adjuntos.";
}

var attachments = Attachments($feature);
var Link = "https://services6.arcgis.com/e5STPBDNmxN8PjAG/arcgis/rest/services/Locales_Nuevos_Adjuntos/FeatureServer/0/";
var complemeto = "/attachments/";


if (Count(attachments) > 1) { 
    var secondAttachment = attachments[1]; 
    var Object = $feature.objectid;
    var Fullurl = Link + Object + complemeto + secondAttachment.id; 

    return Fullurl;
} else {
    return "No hay suficientes adjuntos (se requiere al menos el segundo).";
}

